/* 지붕 (상부 시점에서 페이드) */
var roofMesh=(function(){
  var g=G(null,null);
  var geo=new THREE.BoxGeometry(306,12,236);
  var m=new THREE.Mesh(geo,lam(P.roof,0.96));
  m.position.set(153-CX,176,118-CZ); g.add(m);
  var e=addEdges(g,geo,m,'#969EA6');
  var top=topSurface(g,0,0,182.03,306,236,P.roofTop,0.96);
  return {m:m,e:e,top:top};
})();

/* ============ 전력실 (수배전반4·UPS2·배터리2·소화설비) ============ */
(function(){
  var g=G('switchgear','power');
  for(var i=0;i<4;i++){
    var x=26+i*40;
    box(g,x,22,9,34,22,66,P.yel);
    box(g,x+3,42.5,15,28,2,50,'#F6E4AE');                    /* 도어 */
    box(g,x+6,44,54,10,1.4,7,'#3A3F45',{noedge:true});       /* 계기 디스플레이 */
    box(g,x+20,44,54,8,1.4,7,'#C3542F',{noedge:true});
    for(var s=0;s<3;s++)box(g,x+6,44,20+s*8,22,1.2,2.2,'#C9A94F',{noedge:true}); /* 통풍 슬롯 */
  }
})();
